functions._tiSlug:
function _tiSlug(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 30);
}

// 2026-05-23: subsection-marker detection — (a), (1), (i), (ii), bare
// letter, etc. Pure subsections need two pieces of special handling:
//   (1) Parenting: belong to the nearest non-subsection ancestor (the 6.1
//       above them, NOT the Article above 6.1).
//   (2) Bookmark naming: prefix parent's number so multiple (a)-style
//       subsections across different parents don't collide.
// _cleanHeader strips trailing `).:` so "(a)" arrives as "(a"; tolerate
// both forms.

functions._tiIsPureSubsectionNumber:
function _tiIsPureSubsectionNumber(n) {
  if (!n) return false;
  var inner = String(n).trim().replace(/^[\(\[]/, "").replace(/[\)\]]$/, "");
  if (!inner) return false;
  if (/^[a-z]$/i.test(inner)) return true;
  if (/^\d{1,3}$/.test(inner)) return true;
  if (/^[ivxlcdm]+$/i.test(inner)) return true;
  return false;
}

// Returns the prefix portion of a "5.1(a)"-style number, or null if not
// that pattern. "5.1(a)" → "5.1", "6(b)" → "6", "5.1.2(i)" → "5.1.2".

functions._tiDottedSubsectionPrefix:
function _tiDottedSubsectionPrefix(n) {
  if (!n) return null;
  var m = String(n).match(/^(\d+(?:\.\d+)*)\s*[\(\[]([a-z0-9ivxlcdm]+)\)?\s*$/i);
  return m ? m[1] : null;
}

// 2026-05-23: detect a paragraph that's effectively just template logic
// — strip every {{...}} and [[...]] block plus whitespace/punctuation,
// and check if anything meaningful remains. True for paragraphs like
// "{{IF supplier_type == 'vendor'}}", "[[FOR each]]", "{{ENDIF}}" etc.
// These shouldn't be auto-bookmarked; admin can manually un-skip if they
// really want a bookmark on a control-flow paragraph.

functions._tiIsLogicOnly:
function _tiIsLogicOnly(text) {
  if (!text) return true;
  var stripped = String(text)
    .replace(/\{\{[\s\S]*?\}\}/g, "")
    .replace(/\[\[[\s\S]*?\]\]/g, "")
    .replace(/[\s.,;:!?\-_—–'"`]/g, "");
  return stripped.length === 0;
}

// 2026-05-23: bookmark naming. Word requires names to start with a letter
// (per CLAUDE.md anti-pattern: leading underscore → silent no-op) and
// caps length around 40 chars. Encodes both number and title in the
// name so admin / Office.js can see them via the Bookmark dialog —
// number-first because that's the navigation key admins think in.
// existing: { name: true } map of names already taken in this batch.

functions._tiBookmarkName:
function _tiBookmarkName(number, title, parentArticleNumber, existing) {
  existing = existing || {};
  // 2026-05-23: when section has no own number but lives under a parent
  // article that does (e.g. "Liability Cap" under Article 1), prefix with
  // the parent's number so the bookmark name reflects the document
  // structure: ELI_SEC_1_liability_cap, not ELI_SEC_liability_cap.
  // Also: pure paren subsections like (a)/(1)/(i) prepend parent's number
  // so (a) under 6.1 becomes ELI_SEC_6_1_a_<title> — unique across multiple
  // (a)-style subsections in the same doc.
  var num = number || "";
  var effectiveNumber;
  if (num && _tiIsPureSubsectionNumber(num) && parentArticleNumber) {
    effectiveNumber = parentArticleNumber + "_" + num;
  } else if (num) {
    effectiveNumber = num;
  } else {
    effectiveNumber = parentArticleNumber || "";
  }
  var numSlug = String(effectiveNumber).replace(/[^a-zA-Z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  var titleSlug = _tiSlug(title);
  var base = "ELI_SEC_";
  if (numSlug) base += numSlug + "_";
  base += titleSlug || "untitled";
  // 40-char cap (Word limit)
  base = base.slice(0, 38);
  var name = base;
  var n = 2;
  while (existing[name]) {
    name = base.slice(0, 36) + "-" + n;
    if (name.length > 40) name = name.slice(0, 40);
    n++;
  }
  existing[name] = true;
  return name;
}

functions._tiScanSections:
function _tiScanSections() {
  if (!window.eli || !window.eli.host || typeof window.eli.host.readStructuralMap !== "function") {
    return Promise.reject(new Error("eli.host.readStructuralMap unavailable"));
  }
  return window.eli.host.readStructuralMap({ anchors: false }).then(function (map) {
    if (!map || !Array.isArray(map.headers)) {
      return { headers: [], paragraphCount: 0 };
    }
    var existing = {};
    // 2026-05-23: pre-pass to compute parent article for each header.
    // Walk through headers in order. For each header at level N, parent
    // article is the most recent prior header at level < N. Carries
    // {number, title, level} so downstream rendering and bookmark naming
    // can prefix with parent context (e.g. unnumbered "Liability Cap"
    // under Article 1 → ELI_SEC_1_liability_cap + "↳ Article 1" badge).
    var _kernelHeaders = map.headers;
    // 2026-05-23 BUG FIX: original walk-by-level grabbed any lower-level
    // header as the parent, which incorrectly tagged "Definitions" as
    // belonging to "Recitals" when the doc structure was actually:
    //   RECITALS (level 0)
    //   ARTICLE 1 — DEFINITIONS (level 1)
    //   "Liability Cap" (level 2)
    // Recitals isn't an Article — it's a top-level non-Article header.
    // New rules:
    //   1. If current section's number is dotted (5.1.2), parent is the
    //      header with the prefix number (5.1) — exact number lookup.
    //   2. Otherwise, walk back to the nearest ARTICLE HEADER specifically
    //      (matches "Article N" pattern OR single-integer number ≤ 99).
    //      Skip non-Article headers like Recitals on the way back.
    function _isArticleHeader(h) {
      if (!h) return false;
      var title = String(h.title || h.text || "").trim();
      if (/^\s*Article\b/i.test(title)) return true;
      var num = String(h.number || "").trim();
      if (!num || num === "[Unnumbered]") return false;
      var cleanNum = num.replace(/[.\)\:]+$/, "");
      if (/^\d+$/.test(cleanNum) && Number(cleanNum) <= 99) return true;
      return false;
    }
    // 2026-05-23: exhibit-style container headers (Exhibit A, Schedule 1,
    // Appendix B, Annex II). Treated as valid parent containers — sections
    // detected AFTER an exhibit header belong to that exhibit (until the
    // next exhibit or until admin manually changes the parent).
    function _isExhibitHeader(h) {
      if (!h) return false;
      var title = String(h.title || h.text || "").trim();
      return /^\s*(Exhibit|Appendix|Schedule|Annex)\b/i.test(title);
    }
    function _isContainerHeader(h) {
      return _isArticleHeader(h) || _isExhibitHeader(h);
    }
    function _isExcludedFromParenting(h) {
      var title = String(h.title || h.text || "").trim().toLowerCase();
      return /^\s*(recitals?|whereas|witnesseth|preamble|now,?\s+therefore)\b/.test(title);
    }
    function _cleanHeader(h) {
      var n = String(h.number || "").trim();
      if (n === "[Unnumbered]") n = "";
      if (n) n = n.replace(/[.\)\:]+$/, "");
      var t = String(h.title || h.text || "").trim();
      if (!n) {
        var mm = t.match(/^\s*(\d+(?:\.\d+)*)[\.\)\s]+(.+)$/);
        if (mm) { n = mm[1]; t = mm[2].trim(); }
      }
      // 2026-05-23: when this is an exhibit-style header and the number
      // is still empty, parse "Exhibit A — Schedule of Fees" → number=A,
      // title="Schedule of Fees" so bookmark names + parent inheritance
      // work with the exhibit designator (ELI_SEC_A_payment_terms).
      if (!n) {
        var em = t.match(/^\s*(?:Exhibit|Appendix|Schedule|Annex)\s+([A-Z0-9]+)\s*[—\-:.\s]*(.*)$/i);
        if (em) { n = em[1]; t = (em[2] || "").trim() || t; }
      }
      return { number: n, title: t, level: h.level || 0 };
    }
    function _parentForHeader(currentIdx) {
      var h = _kernelHeaders[currentIdx];
      var current = _cleanHeader(h);
      var currentLevel = h.level || 0;
      // Top-level Article/Exhibit headers have no parent.
      if (_isContainerHeader(h) && (!current.number || current.number.indexOf(".") === -1)) return null;
      // Strategy 1a: dotted-with-suffix subsection ("5.1(a)" / "6(b)").
      // Strip the (a)/(b) suffix, look up the dotted prefix as parent. So
      // 6.1(a) → 6.1 (not Article 6). Level detection on the kernel side
      // sometimes mis-classifies these as siblings of the parent — explicit
      // number lookup beats heuristic walk-back.
      var dotPrefix = _tiDottedSubsectionPrefix(current.number);
      if (dotPrefix) {
        for (var jp = currentIdx - 1; jp >= 0; jp--) {
          var pjp = _cleanHeader(_kernelHeaders[jp]);
          if (pjp.number === dotPrefix) return pjp;
        }
        // Prefix header not found in doc — fall through to other strategies.
      }
      // Strategy 1b: pure paren-marker subsection like "(a)" / "(1)" / "(i)".
      // Walk back, skip other (a)/(b) siblings, return the first real numbered
      // ancestor — typically 6.1, not the Article 6 above it. This is the
      // fix for the user's report: "(a) should belong to 6.1, not the Article".
      if (_tiIsPureSubsectionNumber(current.number)) {
        for (var sk = currentIdx - 1; sk >= 0; sk--) {
          var psk = _kernelHeaders[sk];
          if (_isExcludedFromParenting(psk)) continue;
          var cleanSk = _cleanHeader(psk);
          if (_tiIsPureSubsectionNumber(cleanSk.number)) continue;
          return cleanSk;
        }
        return null;
      }
      // Strategy 2: dotted number ("5.1.2") → look up prefix ("5.1") directly.
      if (current.number && current.number.indexOf(".") !== -1) {
        var parentNum = current.number.split(".").slice(0, -1).join(".");
        for (var j = currentIdx - 1; j >= 0; j--) {
          var pj = _cleanHeader(_kernelHeaders[j]);
          if (pj.number === parentNum) return pj;
        }
      }
      // Strategy 3: walk back; accept first header that is either
      //   - a Container header (Article/Exhibit) — strong parent signal
      //   - OR strictly lower level than current (hierarchy signal)
      // Skip explicit non-parent headers (Recitals, Preamble, etc.) on
      // the way back so they're never returned as parents.
      for (var k = currentIdx - 1; k >= 0; k--) {
        var prev = _kernelHeaders[k];
        if (_isExcludedFromParenting(prev)) continue;
        if (_isContainerHeader(prev)) {
          return _cleanHeader(prev);
        }
        var prevLevel = prev.level || 0;
        if (currentLevel > 0 && prevLevel < currentLevel) {
          return _cleanHeader(prev);
        }
      }
      return null;
    }
    // 2026-05-23: full ancestry chain — walk parent → parent → root.
    // [{ number: "3", title: "Article 3" }, { number: "3.3", title: "..." }]
    // ordered from top-level Article down to immediate parent.
    function _ancestryForHeader(currentIdx) {
      var chain = [];
      var p = _parentForHeader(currentIdx);
      var seenIdx = currentIdx;
      var guard = 0;
      while (p && guard++ < 10) {
        chain.unshift(p);
        // Walk up by finding which header in _kernelHeaders matches p
        var foundIdx = -1;
        for (var i = seenIdx - 1; i >= 0; i--) {
          var c = _cleanHeader(_kernelHeaders[i]);
          if (c.number === p.number && c.title === p.title) { foundIdx = i; break; }
        }
        if (foundIdx === -1) break;
        seenIdx = foundIdx;
        p = _parentForHeader(foundIdx);
      }
      return chain;
    }
    var headers = map.headers.map(function (h, hIdx) {
      var num = String(h.number || "").trim();
      if (num === "[Unnumbered]") num = "";
      var ttl = String(h.title || h.text || "").trim();
      // Detection sometimes lumps the number into the title (e.g.,
      // "5.1 Limitation of Liability"). Split if number's missing AND
      // title leads with a dotted-digit sequence.
      if (!num) {
        var m = ttl.match(/^\s*(\d+(?:\.\d+)*)[\.\)\s]+(.+)$/);
        if (m) { num = m[1]; ttl = m[2].trim(); }
      }
      // 2026-05-23: definitions truncation. Defined terms typically open
      // with a quoted phrase ("Liability Cap" means the maximum amount…)
      // but the whole paragraph gets pulled in as the heading text by
      // the detector. Truncate the title at the matching closing quote
      // so just the defined term is the section name. Handles straight
      // " and curly “”/‘’ quote pairs.
      var QUOTE_CLOSE = { '"': '"', '“': '”', '‘': '’', "'": "'" };
      var firstCh = ttl.charAt(0);
      if (QUOTE_CLOSE.hasOwnProperty(firstCh)) {
        var closeCh = QUOTE_CLOSE[firstCh];
        var closeIdx = ttl.indexOf(closeCh, 1);
        if (closeIdx > 0) ttl = ttl.slice(0, closeIdx + 1);
      }
      var parentArticle = _parentForHeader(hIdx);
      var ancestry = _ancestryForHeader(hIdx);
      // 2026-05-23: detect logic-only headers (paragraph is just
      // {{...}} / [[...]] markers). Per user, NOT auto-skipped — admin
      // decides manually. LOGIC chip stays visible so admin can spot
      // them at a glance.
      var rawText = String(h.text || h.title || "").trim();
      var isLogicOnly = _tiIsLogicOnly(rawText);
      return {
        paragraphIdx: h.idx,
        number: num,
        title: ttl || "(untitled)",
        level: h.level || 0,
        parentArticle: parentArticle,
        ancestry: ancestry,
        originalNumber: num,
        originalTitle: ttl,
        bookmarkName: _tiBookmarkName(num, ttl, parentArticle && parentArticle.number, existing),
        skip: false,
        logicOnly: isLogicOnly,
        edited: false,
      };
    });
    // 2026-05-23: auto-prepend Preamble. The kernel's detector only
    // surfaces header paragraphs; the body text before the first header
    // (title, parties block, recitals, "NOW, THEREFORE…") has no
    // section. Add a virtual "Preamble" header at paragraph 0 so search
    // hits in this region get a real section label + Locate works.
    // Admin can rename, edit number, or skip this row like any other.
    if (headers.length > 0 && headers[0].paragraphIdx > 0) {
      // 2026-05-23: always create Preamble if paragraphs exist before
      // the first detected header. Don't auto-skip based on content —
      // admin decides manually whether to keep, skip, or remove it.
      var preExisting = {};
      headers.forEach(function (h) { preExisting[h.bookmarkName] = true; });
      var preBookmarkName = _tiBookmarkName("", "preamble", null, preExisting);
      headers.unshift({
        paragraphIdx: 0,
        number: "",
        title: "Preamble",
        level: 0,
        parentArticle: null,
        ancestry: [],
        originalNumber: "",
        originalTitle: "Preamble",
        bookmarkName: preBookmarkName,
        skip: false,
        logicOnly: false,
        edited: false,
        autoPrepended: true,
      });
    }
    // 2026-05-23 (Phase B+C): also pass through every paragraph for the
    // "show all paragraphs" view + range grouping. Each entry carries
    // idx, plain text (truncated for preview), isHeader flag, and the
    // logic-only flag so the per-paragraph UI can render efficiently.
    var paragraphsAll = (map.paragraphs || []).map(function (p) {
      var t = String(p.text || "");
      return {
        idx: p.idx,
        text: t,
        preview: t.length > 120 ? t.slice(0, 117) + "…" : t,
        isHeader: !!p.isHeader,
        logicOnly: _tiIsLogicOnly(t),
      };
    });
    return {
      headers: headers,
      paragraphs: paragraphsAll,
      paragraphCount: map.paragraphCount || 0,
    };
  });
}

// Write bookmarks via Word.run. Two modes:
//   smart (default) — diff existing ELI_SEC_* bookmarks against the
//     active set. Leave matching ones alone, insert only new names,
//     delete only orphans. Cheap for incremental re-indexes after small
//     structural changes (admin renamed one section, added one new).
//   force — clear every ELI_SEC_* and write all fresh. Used by the
//     "Clear & Restart" path when admin wants a true reset.

functions._tiApplyBookmarks:
function _tiApplyBookmarks(sections, opts) {
  opts = opts || {};
  var force = !!opts.force;
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    return Promise.reject(new Error("eli.host.runRaw unavailable"));
  }
  var active = sections.filter(function (s) { return !s.skip && s.bookmarkName; });
  if (!active.length) return Promise.resolve({ written: 0, cleared: 0, kept: 0 });
  return window.eli.host.runRaw("template_indexer.apply", function (ctx) {
    var bookmarks = ctx.document.bookmarks;
    bookmarks.load("items/name");
    var paragraphs = ctx.document.body.paragraphs;
    paragraphs.load("items/text");
    return ctx.sync().then(function () {
      var existingByName = {};
      bookmarks.items.forEach(function (bm) {
        if (bm.name && bm.name.indexOf("ELI_SEC_") === 0) existingByName[bm.name] = bm;
      });
      var desiredByName = {};
      active.forEach(function (s) { desiredByName[s.bookmarkName] = s; });
      // 2026-05-23: capture per-bookmark action so the UI can show admin
      // exactly what changed (which bookmarks got written/kept/removed
      // by name). Powers the post-Apply details panel.
      var actionLog = { written: [], kept: [], cleared: [] };
      if (force) {
        Object.keys(existingByName).forEach(function (name) {
          try { existingByName[name].delete(); actionLog.cleared.push(name); } catch (_e) {}
        });
      } else {
        Object.keys(existingByName).forEach(function (name) {
          if (!desiredByName[name]) {
            try { existingByName[name].delete(); actionLog.cleared.push(name); } catch (_e) {}
          } else {
            actionLog.kept.push(name);
          }
        });
      }
      var paraCount = paragraphs.items.length;
      active.forEach(function (s) {
        if (!force && existingByName[s.bookmarkName]) return;
        if (s.paragraphIdx < 0 || s.paragraphIdx >= paraCount) return;
        var p = paragraphs.items[s.paragraphIdx];
        try {
          // 2026-05-23: range bookmark for any section with an explicit
          // endParagraphIdx (Group-dialog manuals + Move-extended detected
          // sections). Point bookmark for implicit-range sections (start
          // only; coverage runs until the next section's start).
          if (typeof s.endParagraphIdx === "number" &&
              s.endParagraphIdx >= s.paragraphIdx && s.endParagraphIdx < paraCount) {
            var lastP = paragraphs.items[s.endParagraphIdx];
            var range = p.getRange("Start").expandTo(lastP.getRange("End"));
            range.insertBookmark(s.bookmarkName);
          } else {
            p.getRange("Start").insertBookmark(s.bookmarkName);
          }
          actionLog.written.push(s.bookmarkName);
        } catch (_e) {}
      });
      return ctx.sync().then(function () {
        return {
          written: actionLog.written.length,
          cleared: actionLog.cleared.length,
          kept: actionLog.kept.length,
          actions: actionLog,
        };
      });
    });
  });
}

functions._tiRenderRow:
function _tiRenderRow(s, idx, nextStartIdx, totalParagraphs) {
  var disabledCls = s.skip ? " _ti_row_skipped" : "";
  var bookmarkPreview = s.skip
    ? '<span style="color:#94a3b8;font-style:italic;">(skipped)</span>'
    : '<code class="_ti_bookmark_name">' + _tiEsc(s.bookmarkName) + '</code>';
  // 2026-05-23: pip now reads "L1"/"L2" instead of just "1"/"2" so it's
  // self-evident as a heading level. Same color coding by level.
  var levelLabel = "L" + (s.level || 0);
  var levelPip = '<span class="_ti_level_pip _ti_level_pip_' + (s.level || 0) + '" title="Heading level ' + (s.level || 0) + ' — 1=top (Article), 2=sub-section, 3=sub-sub, etc.">' + levelLabel + '</span>';
  // 2026-05-23: parent article badge — shows "↳ Article N — Title" when
  // this section lives under a higher-level header. Drives the user's
  // mental model that unnumbered subsections still inherit their parent.
  var parentBadge = "";
  // 2026-05-23: detect Exhibit-vs-Article for nicer labels in the
  // ancestry chain. An ancestor whose title leads with Exhibit/Schedule/
  // Appendix/Annex gets that prefix; otherwise it's an Article.
  function _ancestorLabel(a, isFirst) {
    if (!a) return "";
    var rawTitle = String(a.title || "");
    var typeMatch = rawTitle.match(/^\s*(Exhibit|Appendix|Schedule|Annex)\b/i);
    var num = a.number || "";
    if (typeMatch) {
      // Title already starts with the type — just use the title verbatim
      // (e.g. "Exhibit A — Schedule of Fees" stays whole).
      return rawTitle;
    }
    if (num && isFirst) return "Article " + num + (rawTitle ? " " + rawTitle : "");
    if (num) return num + (rawTitle ? " " + rawTitle : "");
    return rawTitle;
  }
  if (s.ancestry && s.ancestry.length) {
    var chainHtml = s.ancestry.map(function (a, i) {
      return '<span class="_ti_anc_link">' + _tiEsc(_ancestorLabel(a, i === 0)) + '</span>';
    }).join('<span class="_ti_anc_sep"> › </span>');
    parentBadge = '<div class="_ti_parent_article" title="Document hierarchy — full ancestry chain from top-level container down to immediate parent">↳ ' + chainHtml + '</div>';
  } else if (s.parentArticle) {
    var pLabel = _ancestorLabel(s.parentArticle, true);
    parentBadge = '<div class="_ti_parent_article" title="Section lives under this parent header in the document structure">↳ ' + _tiEsc(pLabel) + '</div>';
  }
  // 2026-05-23: paragraph range — makes the section\'s coverage explicit
  // so admin doesn\'t think paragraphs between section starts are being
  // skipped. They\'re body content of the section above.
  var endIdx = (typeof nextStartIdx === "number" ? nextStartIdx - 1 : totalParagraphs - 1);
  var paraRange = s.paragraphIdx === endIdx
    ? "paragraph " + s.paragraphIdx
    : "spans paragraphs " + s.paragraphIdx + "–" + endIdx;
  var logicBadge = s.logicOnly
    ? '<span class="_ti_logic_chip" title="Paragraph contains only template logic ({{...}} / [[...]]) — uncheck the box to skip if you don\'t want a bookmark here.">LOGIC</span>'
    : '';
  var manualBadge = s.isManual
    ? '<span class="_ti_manual_chip" title="Admin-created manual section — uses a range bookmark spanning paragraphs ' + s.paragraphIdx + '–' + s.endParagraphIdx + '">MANUAL</span>'
    : '';
  return '<div class="_ti_row' + disabledCls + (s.logicOnly ? ' _ti_row_logic' : '') + '" data-idx="' + idx + '">' +
    '<input type="checkbox" class="_ti_row_skip" data-act="toggle-skip" data-idx="' + idx + '"' + (s.skip ? "" : " checked") + ' title="' + (s.logicOnly ? "Auto-skipped: logic-only paragraph. Check the box if you want a bookmark here anyway." : "Uncheck to skip this section") + '">' +
    levelPip +
    '<div class="_ti_row_main">' +
      (parentBadge || logicBadge || manualBadge ? '<div class="_ti_parent_row">' + parentBadge + (logicBadge ? ' ' + logicBadge : '') + (manualBadge ? ' ' + manualBadge : '') + '</div>' : '') +
      '<div class="_ti_row_heading">' +
        '<div class="_ti_field_group">' +
          '<label class="_ti_field_label">Number</label>' +
          '<input type="text" class="_ti_input _ti_input_number" data-act="edit-number" data-idx="' + idx + '" value="' + _tiEsc(s.number) + '" placeholder="(none)" title="Section number — e.g. 5.1 — leave blank if unnumbered">' +
        '</div>' +
        '<div class="_ti_field_group">' +
          '<label class="_ti_field_label">Title</label>' +
          '<input type="text" class="_ti_input _ti_input_title" data-act="edit-title" data-idx="' + idx + '" value="' + _tiEsc(s.title) + '" placeholder="Section title" title="Section title">' +
        '</div>' +
      '</div>' +
      '<div class="_ti_row_meta">' +
        '<span class="_ti_meta_label">Bookmark (auto):</span> ' + bookmarkPreview +
        ' <span class="_ti_row_meta_dim">· ' + _tiEsc(paraRange) + '</span>' +
        ' <button class="_ti_row_locate" data-act="locate-row" data-idx="' + idx + '" title="Jump to this section in the open Word document">📍 Locate</button>' +
      '</div>' +
    '</div>' +
  '</div>';
}

// 2026-05-23: clear all ELI_SEC_* bookmarks from the open doc — wipes
// the doc's index without re-applying. Used by "Clear & Restart" to
// give admin a clean slate. Returns {cleared: N} on success.

functions._tiClearAllBookmarks:
function _tiClearAllBookmarks() {
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    return Promise.reject(new Error("eli.host.runRaw unavailable"));
  }
  return window.eli.host.runRaw("template_indexer.clear", function (ctx) {
    var bookmarks = ctx.document.bookmarks;
    bookmarks.load("items/name");
    return ctx.sync().then(function () {
      var cleared = 0;
      bookmarks.items.forEach(function (bm) {
        if (bm.name && bm.name.indexOf("ELI_SEC_") === 0) {
          try { bm.delete(); cleared++; } catch (_e) { /* tolerate */ }
        }
      });
      return ctx.sync().then(function () { return { cleared: cleared }; });
    });
  });
}

// 2026-05-23: Locate handler for indexer row. Selects + scrolls to the
// section's paragraph via Word.run. Lets admin verify each detected
// section is the right paragraph before applying bookmarks.

functions._tiLocateParagraph:
function _tiLocateParagraph(paragraphIdx) {
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    if (typeof showToast === "function") showToast("Word host not available", "err");
    return;
  }
  window.eli.host.runRaw("template_indexer.locate", function (ctx) {
    var paragraphs = ctx.document.body.paragraphs;
    ctx.load(paragraphs, "items");
    return ctx.sync().then(function () {
      if (paragraphIdx < 0 || paragraphIdx >= paragraphs.items.length) {
        throw new Error("paragraph_out_of_range");
      }
      paragraphs.items[paragraphIdx].select();
      return ctx.sync();
    });
  }).then(function () {
    if (typeof showToast === "function") {
      showToast("✓ Selected paragraph " + paragraphIdx + " in document", "ok");
    }
  }).catch(function (err) {
    if (typeof showToast === "function") {
      showToast("Locate failed: " + (err && err.message || "unknown"), "err");
    }
  });
}

functions.showTemplateIndexer:
function showTemplateIndexer() {
  var out = window.eli && window.eli.ui && window.eli.ui.claimOutput
    ? window.eli.ui.claimOutput()
    : document.getElementById("output");
  if (!out) return;
  out.classList.add("eli-view-enter");
  out.innerHTML =
    '<div class="_ti_root">' +
      '<div class="_ti_header">' +
        '<div>' +
          '<div class="_ti_header_eyebrow">ADMIN — RESTRICTED</div>' +
          '<div class="_ti_header_title">🔖 Template Indexer</div>' +
          '<div class="_ti_header_sub" id="_ti_status">Scanning current document…</div>' +
        '</div>' +
        '<div class="_ti_header_btns">' +
          '<span class="_ti_dirty_indicator" id="_ti_dirty_indicator" style="display:none;">● Unsaved changes — click Save &amp; Apply</span>' +
          '<button class="_ti_btn _ti_btn_danger" id="_ti_clear_restart" title="Delete every ELI_SEC_* bookmark from the open doc AND re-run detection from scratch">🗑 Clear &amp; Restart</button>' +
          '<button class="_ti_btn _ti_btn_platinum" id="_ti_rescan" title="Re-run section detection without touching existing bookmarks">↻ Re-scan</button>' +
          '<button class="_ti_btn _ti_btn_gold" id="_ti_apply" disabled>💾 Save &amp; Apply</button>' +
        '</div>' +
      '</div>' +
      '<div class="_ti_explainer">' +
        '<b>Workflow:</b> ' +
        '<b style="color:#0d1b2a;">①</b> Edit section numbers/titles inline below, uncheck sections you don\'t want indexed. ' +
        '<b style="color:#0d1b2a;">②</b> Click <b>💾 Save &amp; Apply</b> to write the bookmarks into the Word doc. ' +
        '<b style="color:#0d1b2a;">③</b> Save the Word doc itself (Ctrl+S). ' +
        '<b style="color:#0d1b2a;">④</b> Re-upload via <b>Build Draft → Settings</b> so the indexed template lands in IDB for template_searcher and other tools to use.' +
      '</div>' +
      '<div class="_ti_body" id="_ti_body">' +
        '<div class="_ti_loading"><span class="_ti_spinner"></span>Reading section structure from <code>eli.host.readStructuralMap</code>…</div>' +
      '</div>' +
    '</div>';
  var state = {
    sections: [],
    paragraphs: [],
    selectedParagraphs: {},
    // 2026-05-23: section selection for bulk re-parent — keyed by
    // section.paragraphIdx (stable across splice/sort) so the selection
    // survives re-renders.
    selectedSections: {},
    lastSelectedIdx: null,
    showAllParagraphs: false,
    scannedAt: 0,
    paragraphCount: 0,
    // 2026-05-23: dirty tracking — toggled true on any edit
    // (skip toggle, number/title input, remove, manual group), cleared
    // after a successful Apply. Drives the "Unsaved changes" indicator.
    dirty: false,
    lastApply: null,
  };
  function _markDirty() {
    state.dirty = true;
    _updateDirtyIndicator();
  }
  // 2026-05-23: defensive — sort state.sections by paragraphIdx so the
  // map is always in document order no matter what mutation just ran
  // (Remove, Move, Group, manual insert). Called from every state-changing
  // path so the user never sees the map out of order.
  function _sortSections() {
    state.sections.sort(function (a, b) {
      return (a.paragraphIdx || 0) - (b.paragraphIdx || 0);
    });
  }
  function _clearDirty() {
    state.dirty = false;
    _updateDirtyIndicator();
  }
  function _updateDirtyIndicator() {
    var ind = out && out.querySelector("#_ti_dirty_indicator");
    if (!ind) return;
    if (state.dirty) {
      ind.style.display = "inline-flex";
      ind.textContent = "● Unsaved changes — click Save & Apply";
    } else {
      ind.style.display = "none";
    }
  }
  var bodyEl = out.querySelector("#_ti_body");
  var statusEl = out.querySelector("#_ti_status");
  var applyBtn = out.querySelector("#_ti_apply");
  var rescanBtn = out.querySelector("#_ti_rescan");
  function _renderBody() {
    if (!state.sections.length) {
      bodyEl.innerHTML = '<div class="_ti_empty">' +
        '<div class="_ti_empty_icon">∅</div>' +
        '<div class="_ti_empty_title">No sections detected</div>' +
        '<div class="_ti_empty_sub">The current document has no headings recognizable to <code>readStructuralMap</code>. ' +
        'Use Word\'s Heading 1/2/3 styles, numbered lists, or ALL-CAPS short paragraphs to mark sections.</div>' +
      '</div>';
      applyBtn.disabled = true;
      return;
    }
    // 2026-05-23: snapshot per-section open state BEFORE the re-render
    // (keyed by section paragraphIdx — stable across splice/move/edit),
    // plus the Legend details. Restore after innerHTML rebuild so admin
    // doesn't have to re-open whichever section they were editing.
    var groupOpenMap = {};
    bodyEl.querySelectorAll("._ti_pgroup[data-section-pidx]").forEach(function (g) {
      var pidx = g.getAttribute("data-section-pidx");
      if (pidx != null) groupOpenMap[pidx] = g.open;
    });
    var prevLegendOpen = false;
    var legEl = bodyEl.querySelector("._ti_legend");
    if (legEl) prevLegendOpen = legEl.open;
    // Defensive: sort by paragraphIdx so the map renders in document
    // order no matter what mutation just landed.
    _sortSections();
    var activeCount = state.sections.filter(function (s) { return !s.skip; }).length;
    var manualCount = state.sections.filter(function (s) { return s.isManual; }).length;
    bodyEl.innerHTML =
      '<div class="_ti_summary">' +
        '<span class="_ti_summary_count">' + activeCount + '</span> ' +
        ' of ' + state.sections.length + ' sections will be bookmarked' +
        (manualCount ? ' · <span class="_ti_summary_manual">' + manualCount + ' manual</span>' : '') + ' · ' +
        state.paragraphs.length + ' paragraphs total · click a section to expand' +
      '</div>' +
      '<details class="_ti_legend">' +
        '<summary class="_ti_legend_summary">❓ What do the controls mean? (click to expand)</summary>' +
        '<div class="_ti_legend_body">' +
          '<div class="_ti_legend_row"><span class="_ti_level_pip _ti_level_pip_1">L1</span> Heading level — L1 = top-level (Article), L2 = sub-section (5.1), L3 = sub-sub.</div>' +
          '<div class="_ti_legend_row"><span class="_ti_para_header_chip">H</span> Word detected this paragraph as a heading.</div>' +
          '<div class="_ti_legend_row"><span class="_ti_logic_chip">LOGIC</span> Paragraph is just template control ({{...}} / [[...]]) — no real content.</div>' +
          '<div class="_ti_legend_row"><span class="_ti_manual_chip">MANUAL</span> Admin-created section (range bookmark).</div>' +
          '<div class="_ti_legend_row"><span class="_ti_parent_article">↳ Article 1 …</span> Document hierarchy — where this section lives in the parent structure.</div>' +
          '<div class="_ti_legend_row"><b>☑ INCLUDE / ☐ SKIPPED</b> — whether this section\'s bookmark gets written on Save & Apply.</div>' +
          '<div class="_ti_legend_row"><b>📍 Locate</b> — jumps Word to this section / paragraph so you can verify.</div>' +
          '<div class="_ti_legend_row"><b>↪ Move</b> (on paragraph rows) — moves the paragraph into a different section.</div>' +
          '<div class="_ti_legend_row"><b>✕ Remove</b> — deletes this section from the indexer (false positives). Paragraphs roll up to the previous section. Click ↻ Re-scan to restore detection.</div>' +
          '<div class="_ti_legend_row"><b>+ Make Section</b> (on paragraph rows) — promotes a paragraph into a new section in one click.</div>' +
          '<div class="_ti_legend_row"><b>Paragraph checkboxes</b> — for batch selection only (multi-select + 📦 Group as new section). They do NOT include/exclude individual paragraphs.</div>' +
        '</div>' +
      '</details>' +
      _renderParagraphGroups();
    applyBtn.disabled = activeCount === 0;
    // Restore Legend open state + per-section open states.
    if (prevLegendOpen) {
      var newLegEl = bodyEl.querySelector("._ti_legend");
      if (newLegEl) newLegEl.open = true;
    }
    bodyEl.querySelectorAll("._ti_pgroup[data-section-pidx]").forEach(function (g) {
      var pidx = g.getAttribute("data-section-pidx");
      if (pidx in groupOpenMap) g.open = groupOpenMap[pidx];
    });
  }
  // 2026-05-23: preview map — dry-run view of what Save & Apply will
  // produce. Shows the final section tree in document order, indented
  // by ancestry depth, with bookmark name + paragraph range per row.
  // Skipped sections rendered with strikethrough so admin sees exactly
  // what won't get a bookmark. Updates live with every edit.
  function _renderPreviewMap() {
    if (!state.sections || !state.sections.length) return "";
    var activeCount = state.sections.filter(function (s) { return !s.skip; }).length;
    var skipCount = state.sections.length - activeCount;
    // Sort by paragraphIdx for stable document order.
    var sorted = state.sections.slice().sort(function (a, b) {
      return (a.paragraphIdx || 0) - (b.paragraphIdx || 0);
    });
    var rows = sorted.map(function (s) {
      var depth = (s.ancestry && s.ancestry.length) || 0;
      var indent = depth * 18;
      var skippedCls = s.skip ? " _ti_preview_row_skipped" : "";
      var manualBadge = s.isManual
        ? '<span class="_ti_manual_chip" style="font-size:8.5px;">M</span>'
        : '';
      var skipBadge = s.skip
        ? '<span class="_ti_preview_skip_badge">SKIPPED</span>'
        : '';
      var numHtml = s.number
        ? '<span class="_ti_preview_num">' + _tiEsc(s.number) + '</span>'
        : (s.parentArticle && s.parentArticle.number
            ? '<span class="_ti_preview_num _ti_preview_num_inherited" title="Inherits parent\'s number">' + _tiEsc(s.parentArticle.number) + '</span>'
            : '<span class="_ti_preview_num _ti_preview_num_empty">—</span>');
      var rangeEnd;
      if (s.isManual && typeof s.endParagraphIdx === "number") {
        rangeEnd = s.endParagraphIdx;
      } else {
        rangeEnd = state.paragraphCount - 1;
        for (var j = sorted.indexOf(s) + 1; j < sorted.length; j++) {
          if (!sorted[j].isManual) { rangeEnd = sorted[j].paragraphIdx - 1; break; }
        }
      }
      var rangeText = s.paragraphIdx === rangeEnd
        ? "¶" + s.paragraphIdx
        : "¶" + s.paragraphIdx + "–" + rangeEnd;
      // 2026-05-23: row is clickable — jumps Word to this section's start
      // paragraph. data-act="locate-preview" routed through out.onclick.
      return '<div class="_ti_preview_row' + skippedCls + '" style="padding-left:' + (10 + indent) + 'px;" ' +
        'data-act="locate-preview" data-pidx="' + s.paragraphIdx + '" ' +
        'title="Click to jump to this section in Word (paragraph ' + s.paragraphIdx + ')">' +
        numHtml +
        '<span class="_ti_preview_title">' + _tiEsc(s.title || s.bookmarkName) + '</span>' +
        manualBadge + skipBadge +
        '<span class="_ti_preview_range">' + rangeText + '</span>' +
        (s.skip ? '' : '<code class="_ti_preview_bm">' + _tiEsc(s.bookmarkName) + '</code>') +
      '</div>';
    }).join("");
    return '<details class="_ti_preview">' +
      '<summary class="_ti_preview_summary">📋 Preview map — ' +
        activeCount + ' bookmarks will be written' +
        (skipCount ? ' · ' + skipCount + ' skipped' : '') +
        ' (click to expand)' +
      '</summary>' +
      '<div class="_ti_preview_body">' + rows + '</div>' +
    '</details>';
  }
  // 2026-05-23 (Phase B+C v2): paragraph-first view — every paragraph
  // visible, grouped under its current section assignment. Each section
  // group is collapsible (open by default) so admin sees the full
  // structure at a glance. Multi-select + manual-grouping still work.
  function _renderParagraphGroups() {
    if (!state.paragraphs || !state.paragraphs.length) return "";
    var selectedCount = Object.keys(state.selectedParagraphs).length;
    // Walk paragraphs, bucket into groups keyed by section assignment.
    // Groups appear in document order. "No section" rows form a separate
    // group at the start if the doc has pre-section paragraphs.
    function _sectionForParagraph(pidx) {
      // 2026-05-23: two-pass lookup keyed on endParagraphIdx (NOT isManual).
      // Pass 1: sections with an explicit endParagraphIdx — these are
      //   either Group-dialog manual sections OR detected sections that the
      //   admin extended via Move. Either way, the range is explicit and
      //   wins over neighboring implicit ranges.
      // Pass 2: sections without endParagraphIdx — implicit range running
      //   from their start to the next implicit-range section's start - 1,
      //   skipping explicit-range sections (they're carved out).
      // Walk reverse within each pass so the most recent / most specific
      // match returns first.
      for (var mi = state.sections.length - 1; mi >= 0; mi--) {
        var ms = state.sections[mi];
        if (typeof ms.endParagraphIdx !== "number") continue;
        if (pidx >= ms.paragraphIdx && pidx <= ms.endParagraphIdx) {
          return { section: ms, idx: mi };
        }
      }
      for (var i = state.sections.length - 1; i >= 0; i--) {
        var s = state.sections[i];
        if (typeof s.endParagraphIdx === "number") continue;
        var sStart = s.paragraphIdx;
        if (pidx < sStart) continue;
        var sEnd = state.paragraphCount - 1;
        for (var j = i + 1; j < state.sections.length; j++) {
          if (typeof state.sections[j].endParagraphIdx !== "number") {
            sEnd = state.sections[j].paragraphIdx - 1;
            break;
          }
        }
        if (pidx <= sEnd) return { section: s, idx: i };
      }
      return null;
    }
    var groups = []; // [{ section, paragraphs, headerHtml }]
    var noSectionParagraphs = [];
    var currentGroup = null;
    state.paragraphs.forEach(function (p) {
      var found = _sectionForParagraph(p.idx);
      if (!found) {
        noSectionParagraphs.push(p);
        currentGroup = null;
        return;
      }
      if (!currentGroup || currentGroup.section !== found.section) {
        currentGroup = { section: found.section, paragraphs: [], idx: found.idx };
        groups.push(currentGroup);
      }
      currentGroup.paragraphs.push(p);
    });
    var html = '<div class="_ti_paragraph_groups_wrap">' +
      '<div class="_ti_pg_header">' +
        '<div class="_ti_pg_title_row">' +
          '<div class="_ti_pg_title">📋 Document Structure Map</div>' +
          '<div class="_ti_pg_expand_btns">' +
            '<button class="_ti_btn _ti_btn_platinum" data-act="expand-all" title="Expand every section to show its paragraphs">⤓ Expand All</button>' +
            '<button class="_ti_btn _ti_btn_platinum" data-act="collapse-all" title="Collapse every section back to a single row">⤒ Collapse All</button>' +
          '</div>' +
        '</div>' +
        '<div class="_ti_pg_help">' +
          'Every section + paragraph in document order, indented by hierarchy depth. ' +
          'Sections start <b style="color:#0d1b2a;">collapsed</b> — click any row (or its ▸ chevron) to expand and see its paragraphs. ' +
          'Edit number / title inline, ✕ Remove false positives, ↪ Move stray paragraphs into the right section, ' +
          '📦 Group selected paragraphs into a new manual section.' +
        '</div>' +
      '</div>';
    if (noSectionParagraphs.length) {
      html += _renderParagraphGroup({
        section: null,
        paragraphs: noSectionParagraphs,
        titleHtml: '<span style="color:#94a3b8;font-style:italic;">(no section — before first bookmark)</span>',
      }, "no-section");
    }
    groups.forEach(function (g, gi) {
      var s = g.section;
      // 2026-05-23 (Phase 1 v3): unified inline-editable group header.
      // No separate "Edit detected sections" panel — admin edits number /
      // title / skip / locate right here on the group header. Each input
      // is wired via data-section-idx (the index into state.sections) so
      // _refreshAllParagraphsView's selective re-render preserves focus.
      var sIdx = g.idx; // index into state.sections
      var skipChecked = s.skip ? "" : " checked";
      var manualChip = s.isManual ? '<span class="_ti_manual_chip">M</span>' : '';
      var logicChip = s.logicOnly ? '<span class="_ti_logic_chip">LOGIC</span>' : '';
      var skipChip = s.skip ? '<span class="_ti_preview_skip_badge">SKIPPED</span>' : '';
      var levelLabel = "L" + (s.level || 0);
      var levelPip = '<span class="_ti_level_pip _ti_level_pip_' + (s.level || 0) + '" title="Heading level ' + (s.level || 0) + '">' + levelLabel + '</span>';
      // Ancestry chain for the expanded body (compact summary intentionally
      // skips it — depth is already shown by indentation).
      var parentChip = "";
      if (s.ancestry && s.ancestry.length) {
        var chainHtml = s.ancestry.map(function (a) {
          var rawTitle = String(a.title || "");
          var label = /^\s*(Exhibit|Appendix|Schedule|Annex)\b/i.test(rawTitle)
            ? rawTitle
            : (a.number ? a.number + (rawTitle ? " " + rawTitle : "") : rawTitle);
          return _tiEsc(label);
        }).join(' › ');
        parentChip = '<span class="_ti_parent_article" title="Document hierarchy">↳ ' + chainHtml + '</span>';
      }
      // 2026-05-23: COMPACT map summary — single line, looks like the old
      // Preview Map row. Number + title + chips + range + bookmark + 📍 + ✕.
      // Inline onclick on both buttons cancels the parent <summary>'s
      // details-toggle so clicking 📍 / ✕ doesn't expand/collapse the row.
      var numHtml = s.number
        ? '<span class="_ti_map_num">' + _tiEsc(s.number) + '</span>'
        : (s.parentArticle && s.parentArticle.number
            ? '<span class="_ti_map_num _ti_map_num_inherited" title="Inherits parent\'s number">' + _tiEsc(s.parentArticle.number) + '</span>'
            : '<span class="_ti_map_num _ti_map_num_empty">—</span>');
      var paraCount = g.paragraphs.length;
      var rangeText = '¶' + g.paragraphs[0].idx + (paraCount > 1 ? '–¶' + g.paragraphs[paraCount - 1].idx : '');
      var bookmarkChip = s.skip
        ? '<span class="_ti_map_bm_skipped">(skipped)</span>'
        : '<code class="_ti_map_bm">' + _tiEsc(s.bookmarkName) + '</code>';
      // 2026-05-23: prominent count chip when section has > 1 paragraph
      // so admin can tell at a glance which sections contain real content
      // vs which are header-only. Color/size scales subtly with count.
      var countSizeCls = paraCount >= 10 ? " _ti_map_count_chip_big" : "";
      var countChip = paraCount > 1
        ? '<span class="_ti_map_count_chip' + countSizeCls + '" title="' + paraCount + ' paragraphs in this section — click row to expand and see them">📄 ' + paraCount + ' ¶' + (paraCount === 1 ? '' : 's') + '</span>'
        : '<span class="_ti_map_count_chip_single" title="Header only — no body paragraphs">header only</span>';
      // 2026-05-23: section-selection checkbox for bulk re-parent. Keyed by
      // paragraphIdx (stable). onclick stopPropagation so toggling doesn't
      // expand/collapse the section.
      var sectionSelChecked = state.selectedSections[s.paragraphIdx] ? " checked" : "";
      var sectionSelBox = '<input type="checkbox" class="_ti_map_section_select" data-act="toggle-section-select" data-pidx="' + s.paragraphIdx +
        '"' + sectionSelChecked +
        ' onclick="event.stopPropagation()" title="Select this section for bulk re-parent">';
      var summaryHtml =
        sectionSelBox +
        numHtml +
        '<span class="_ti_map_title_text">' + _tiEsc(s.title || "(untitled)") + '</span>' +
        manualChip + logicChip + skipChip +
        countChip +
        '<span class="_ti_map_range_text">' + rangeText + '</span>' +
        bookmarkChip +
        '<div class="_ti_map_btns">' +
          '<button class="_ti_map_btn _ti_map_btn_locate" data-act="locate-row" data-idx="' + sIdx +
            '" onclick="event.preventDefault()" title="Jump to this section\'s start paragraph in Word">📍</button>' +
          '<button class="_ti_map_btn _ti_map_btn_remove" data-act="remove-section" data-idx="' + sIdx +
            '" onclick="event.preventDefault()" title="Remove this section (false positive). Paragraphs roll up to the previous section. Click ↻ Re-scan to restore detection.">✕</button>' +
        '</div>';
      // BODY (shown when expanded): parent ancestry + editor + paragraph list.
      var editorHtml =
        '<div class="_ti_map_editor">' +
          '<label class="_ti_pg_skip" title="' +
            (s.skip
              ? 'Currently SKIPPED — bookmark will NOT be written. Re-check to include.'
              : 'Currently INCLUDED — bookmark will be written. Uncheck to skip (paragraphs roll up to previous section).') +
          '">' +
            '<input type="checkbox" data-act="toggle-skip" data-idx="' + sIdx + '"' + skipChecked + '>' +
            '<span class="_ti_pg_skip_lbl">' + (s.skip ? "SKIPPED" : "INCLUDE") + '</span>' +
          '</label>' +
          levelPip +
          '<div class="_ti_pg_fields">' +
            '<input type="text" class="_ti_input _ti_input_number _ti_pg_num_input" data-act="edit-number" data-idx="' + sIdx + '" value="' + _tiEsc(s.number) + '" placeholder="' +
              (!s.number && s.parentArticle && s.parentArticle.number
                ? "(inherits " + _tiEsc(s.parentArticle.number) + ")"
                : "#") + '" title="Section number (e.g. 5.1). Empty = inherits parent\'s number for the bookmark name.">' +
            '<input type="text" class="_ti_input _ti_pg_ttl_input" data-act="edit-title" data-idx="' + sIdx + '" value="' + _tiEsc(s.title) + '" placeholder="Section title" title="Section title">' +
          '</div>' +
        '</div>';
      // 2026-05-23: parent picker — lets admin manually re-parent a section
      // (e.g. move "Affiliate" to belong to Article 1). Lists every other
      // section that starts at or before this one (parent must come first
      // in the doc). Selecting updates parentArticle + ancestry + level
      // so the section re-indents under the new parent in the map.
      var parentOptionsHtml = state.sections.map(function (sec, secIdx) {
        if (secIdx === sIdx) return '';
        if (sec.paragraphIdx > s.paragraphIdx) return '';
        var lbl = (sec.number ? sec.number + " " : "") + (sec.title || "(untitled)") + " · ¶" + sec.paragraphIdx;
        var matches = s.parentArticle && s.parentArticle.number === (sec.number || "") && s.parentArticle.title === (sec.title || "");
        return '<option value="' + secIdx + '"' + (matches ? ' selected' : '') + '>' + _tiEsc(lbl) + '</option>';
      }).join("");
      var parentPickerHtml =
        '<div class="_ti_map_parent_picker">' +
          '<label class="_ti_map_parent_label">Belongs to (parent):</label>' +
          '<select class="_ti_map_parent_select" data-act="reparent-section" data-idx="' + sIdx + '" title="Set this section\'s parent — controls where it sits in the map hierarchy + ancestry chain + bookmark prefix">' +
            '<option value="-1"' + (!s.parentArticle ? ' selected' : '') + '>(top level — no parent)</option>' +
            parentOptionsHtml +
          '</select>' +
        '</div>';
      var bodyHtml =
        (parentChip ? '<div class="_ti_map_parent_row">' + parentChip + '</div>' : '') +
        editorHtml +
        parentPickerHtml +
        '<div class="_ti_map_paragraphs">' +
          g.paragraphs.map(function (p, pi) {
