  border: 1px solid #cbd5e1;
  border-radius: 6px;
  box-shadow: 0 12px 36px rgba(15, 23, 42, 0.25);
  display: flex;
  flex-direction: column;
  max-height: 380px;
  overflow: hidden;
}
._ti_mvp_head {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  padding: 8px 12px;
  font: 700 11px/1.3 Inter, sans-serif;
  border-bottom: 2px solid #c9a227;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
._ti_mvp_close {
  background: transparent;
  border: none;
  color: #c9a227;
  font-size: 14px;
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 3px;
}
._ti_mvp_close:hover { background: rgba(201, 162, 39, 0.2); }
._ti_mvp_list {
  overflow-y: auto;
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
._ti_mvp_item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  font: 600 11.5px/1.3 Inter, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  border: 1px solid transparent;
  border-radius: 4px;
  cursor: pointer;
  text-align: left;
  transition: all 0.1s;
}
._ti_mvp_item:hover:not(:disabled) {
  background: #fffbeb;
  border-color: #c9a227;
}
._ti_mvp_item:disabled {
  background: #f1f5f9;
  color: #94a3b8;
  cursor: not-allowed;
}
._ti_mvp_current { background: #ecfdf5 !important; }
._ti_mvp_current_tag {
  font-size: 9px;
  color: #047857;
  font-weight: 700;
  margin-left: auto;
}
._ti_mvp_chip {
  display: inline-block;
  font: 800 8px/1 Inter, sans-serif;
  background: #fef3c7;
  color: #6d4c0f;
  padding: 2px 5px;
  border-radius: 3px;
  letter-spacing: 0.5px;
}
._ti_mvp_start {
  font-family: ui-monospace, Consolas, monospace;
  font-size: 10px;
  color: #64748b;
  min-width: 38px;
}
._ti_mvp_foot {
  padding: 7px 12px;
  font: 500 9.5px/1.4 Inter, sans-serif;
  color: #64748b;
  background: #f8fafc;
  border-top: 1px solid #e2e8f0;
}

/* 2026-05-23: per-paragraph Locate button (sits before Move). */
._ti_para_locate {
  padding: 3px 8px;
  font: 700 9px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #1565c0;
  background: linear-gradient(180deg, #ffffff 0%, #eff6ff 100%);
  border: 1px solid #93c5fd;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.12s;
  margin-right: 4px;
}
._ti_para_locate:hover {
  background: linear-gradient(180deg, #dbeafe 0%, #bfdbfe 100%);
  border-color: #1565c0;
}

/* 2026-05-23: unified map look — sections are collapsed by default and
   depth-indented (via inline margin-left). Manual sections get a subtle
   gold left border so admin can tell them apart at a glance. */
._ti_pgroup_manual > summary { border-left: 3px solid #c9a227; }
._ti_pgroup {
  margin-top: 4px;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  background: #fff;
  transition: box-shadow 0.12s;
}
._ti_pgroup:hover { box-shadow: 0 1px 4px rgba(15, 23, 42, 0.06); }
._ti_pgroup[open] {
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.08);
  border-color: #cbd5e1;
}
/* Subtle disclosure chevron on the right edge of the summary. */
._ti_pgroup > summary {
  list-style: none;
  cursor: pointer;
  position: relative;
}
._ti_pgroup > summary::-webkit-details-marker { display: none; }
._ti_pgroup > summary::after {
  content: "▸";
  position: absolute;
  right: 12px;
  top: 12px;
  color: #94a3b8;
  font-size: 12px;
  transition: transform 0.15s;
}
._ti_pgroup[open] > summary::after { transform: rotate(90deg); }

/* 2026-05-23: Map header — title + Expand/Collapse All buttons on one row. */
._ti_pg_title_row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 6px;
}
._ti_pg_expand_btns {
  display: flex;
  gap: 6px;
}
._ti_pg_expand_btns ._ti_btn {
  padding: 5px 10px;
  font: 700 9.5px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
}

/* 2026-05-23: compact map summary row — looks like the old Preview Map
   (single line, number + title + chips + range + bookmark + actions),
   with the full section editor + paragraph list living in the expanded
   body. The chevron we set in ._ti_pgroup styles still works for these. */
._ti_map_summary {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 36px 8px 12px;
  font: 600 11.5px/1.3 Inter, sans-serif;
  color: #0f172a;
}
._ti_map_num {
  font-family: ui-monospace, Consolas, monospace;
  font-weight: 800;
  color: #0d1b2a;
  background: #fef3c7;
  padding: 2px 7px;
  border-radius: 3px;
  font-size: 11px;
  min-width: 28px;
  text-align: center;
  flex-shrink: 0;
}
._ti_map_num_inherited {
  background: #ede9fe;
  color: #6d28d9;
  font-style: italic;
  font-weight: 700;
}
._ti_map_num_empty {
  background: #f1f5f9;
  color: #94a3b8;
  font-weight: 500;
}
._ti_map_title_text {
  flex: 1 1 auto;
  font-weight: 600;
  color: #0f172a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}
._ti_map_range_text {
  font-family: ui-monospace, Consolas, monospace;
  font-size: 10px;
  color: #64748b;
  flex-shrink: 0;
}

/* 2026-05-23: prominent paragraph-count chip — shows on multi-paragraph
   sections so admin can tell at a glance which sections contain real
   content. "header only" for single-paragraph sections (the header alone). */
._ti_map_count_chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 9px;
  font: 800 10px/1 Inter, sans-serif;
  letter-spacing: 0.3px;
  color: #5b21b6;
  background: linear-gradient(180deg, #f5f3ff 0%, #ede9fe 100%);
  border: 1px solid #c4b5fd;
  border-radius: 10px;
  flex-shrink: 0;
  white-space: nowrap;
}
._ti_map_count_chip_big {
  padding: 4px 11px;
  font-size: 11px;
  color: #4c1d95;
  background: linear-gradient(180deg, #ede9fe 0%, #ddd6fe 100%);
  border-color: #a78bfa;
  font-weight: 800;
}
._ti_map_count_chip_single {
  display: inline-flex;
  padding: 2px 8px;
  font: 600 9px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #94a3b8;
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  flex-shrink: 0;
}
._ti_map_bm {
  font-family: ui-monospace, Consolas, monospace;
  background: #dbeafe;
  color: #1e40af;
  padding: 2px 6px;
  border-radius: 3px;
  font-size: 10px;
  font-weight: 600;
  border: 1px dashed #93c5fd;
  flex-shrink: 0;
}
._ti_map_bm_skipped {
  color: #94a3b8;
  font-style: italic;
  font-size: 10.5px;
  flex-shrink: 0;
}
._ti_map_btns {
  display: flex;
  gap: 4px;
  margin-left: 2px;
  flex-shrink: 0;
}
._ti_map_btn {
  padding: 3px 7px;
  font-size: 11px;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.12s;
  line-height: 1;
}
._ti_map_btn_locate:hover {
  background: #eff6ff;
  border-color: #1565c0;
}
._ti_map_btn_remove { color: #b91c1c; }
._ti_map_btn_remove:hover {
  background: #fef2f2;
  border-color: #b91c1c;
}

/* Expanded body — parent ancestry strip, editor, paragraphs. */
._ti_map_parent_row {
  padding: 6px 12px;
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
  font-size: 11px;
}
._ti_map_editor {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: #fafbfc;
  border-bottom: 1px solid #e2e8f0;
  flex-wrap: wrap;
}
._ti_map_paragraphs { padding: 4px 0 6px; }

/* 2026-05-23: per-section "Belongs to" parent picker — sits between the
   editor and paragraph list in the expanded body. */
._ti_map_parent_picker {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: #fafbfc;
  border-bottom: 1px solid #e2e8f0;
}
._ti_map_parent_label {
  font: 800 9px/1 Inter, sans-serif;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: #94a3b8;
  flex-shrink: 0;
}
._ti_map_parent_select {
  flex: 1 1 auto;
  padding: 6px 8px;
  font: 600 11.5px/1.3 Inter, sans-serif;
  color: #0f172a;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  min-width: 0;
  cursor: pointer;
}
._ti_map_parent_select:focus {
  outline: none;
  border-color: #c9a227;
  background: #fffbeb;
}
._ti_map_parent_select:hover { border-color: #94a3b8; }

/* 2026-05-23: bulk-select checkbox on each map summary row. Small +
   unobtrusive; selected rows get a subtle gold tint. */
._ti_map_section_select {
  margin: 0 4px 0 0;
  flex-shrink: 0;
  cursor: pointer;
  accent-color: #c9a227;
}
._ti_pgroup > summary:has(._ti_map_section_select:checked) {
  background: linear-gradient(90deg, rgba(201, 162, 39, 0.10) 0%, rgba(201, 162, 39, 0.02) 100%);
  border-left: 3px solid #c9a227;
}

/* 2026-05-23: "+ Make Section" disabled when paragraph isn't at the
   bottom of its section. Promoting a middle paragraph would split the
   section visually — admin works bottom-up instead. */
._ti_para_promote_disabled {
  opacity: 0.4;
  cursor: not-allowed !important;
  background: #f1f5f9 !important;
  color: #94a3b8 !important;
  border-color: #e2e8f0 !important;
}
._ti_para_promote_disabled:hover {
  background: #f1f5f9 !important;
  border-color: #e2e8f0 !important;
}
